insert into kofi.demo_artists (id, user_id, working_name, legal_name, pronouns, bio, statement, region_city, region_region, region_country, region_precision, mediums, career_stage, experience_commissions, experience_public_art, experience_residencies, experience_institutional_shows, experience_years_practicing, availability_commissions, availability_sales, availability_exhibitions, links, contact_email, contact_phone, contact_studio_address, kofi_notes, visibility, status, consent_version, consent_accepted_at, avatar_color, created_at, updated_at, verification_token, imports) values
  ('20000000-0000-4000-8000-000000000001'::uuid, '10000000-0000-4000-8000-000000000001'::uuid, 'Mara Oyelaran', 'Omolara Oyelaran-Whitfield', 'she/her', 'Large-format oil painter working from a converted print shop in Pittsburgh. Mara builds surfaces in thin, repeated glazes until the color reads as light rather than pigment.', 'I paint the hour after a storm, when the city is wet enough to double itself. The work is slow because the light is fast.', 'Pittsburgh', 'Pennsylvania', 'United States', 'city', array['painting', 'drawing']::kofi.medium[], 'mid-career', true, true, true, true, 14, true, true, true, '[{"label":"Website","url":"https://www.mara-oyelaran.com","platform":"website","handle":"mara-oyelaran.com","verification":"claimed"},{"label":"Instagram","url":"https://www.instagram.com/mara.paints","platform":"instagram","handle":"@mara.paints","verification":"verified","checkedAt":"2026-07-23T12:00:00.000Z"}]'::jsonb, 'mara@example.com', '+1 412 555 0142', '19 Foundry St, Pittsburgh, PA', 'Onboarded Sept 2026. Strong fit for the airport commission call.', 'public', 'approved', '2026-10-v1', '2026-07-23T12:00:00.000Z'::timestamptz, '#2436F5', '2026-07-18T12:00:00.000Z'::timestamptz, '2026-08-29T12:00:00.000Z'::timestamptz, 'kofi-7f3a2k', '[{"source":{"label":"Instagram","url":"https://www.instagram.com/mara.paints","platform":"instagram","handle":"@mara.paints","verification":"claimed"},"fetchedAt":"2026-07-18T12:00:00.000Z","appliedFields":["workingName"],"notes":[]},{"source":{"label":"Website","url":"https://www.mara-oyelaran.com","platform":"website","handle":"mara-oyelaran.com","verification":"claimed"},"fetchedAt":"2026-07-18T12:00:00.000Z","appliedFields":["city","region","country"],"notes":[]}]'::jsonb),
  ('20000000-0000-4000-8000-000000000002'::uuid, '10000000-0000-4000-8000-000000000002'::uuid, 'Tobias Reinholt', null, 'he/him', 'Ceramicist and installation artist. Tobias fires stoneware vessels at the edge of collapse and shows them in groups that behave like crowds.', null, 'Braddock', 'Pennsylvania', 'United States', 'region', array['ceramics', 'sculpture', 'installation']::kofi.medium[], 'established', true, true, true, true, 22, true, true, true, '[{"label":"Website","url":"https://example.com/tobias","platform":"website","handle":"example.com","verification":"claimed"}]'::jsonb, 'tobias@example.com', null, null, null, 'public', 'approved', '2026-10-v1', '2026-07-25T12:00:00.000Z'::timestamptz, '#FF5C39', '2026-07-19T12:00:00.000Z'::timestamptz, '2026-08-22T12:00:00.000Z'::timestamptz, 'kofi-tr9c6m', '[]'::jsonb),
  ('20000000-0000-4000-8000-000000000003'::uuid, '10000000-0000-4000-8000-000000000003'::uuid, 'June Takahashi-Bell', null, 'they/them', 'Textile artist weaving with reclaimed industrial thread and hand-dyed wool. June’s wall works are built to be touched.', null, 'Ottawa', 'Ontario', 'Canada', 'city', array['textile', 'mixed media']::kofi.medium[], 'emerging', false, false, true, false, 4, true, true, true, '[{"label":"Instagram","url":"https://www.instagram.com/june.weaves","platform":"instagram","handle":"@june.weaves","verification":"claimed"}]'::jsonb, 'june@example.com', null, null, null, 'public', 'approved', '2026-10-v1', '2026-08-02T12:00:00.000Z'::timestamptz, '#CFFF4A', '2026-07-30T12:00:00.000Z'::timestamptz, '2026-08-27T12:00:00.000Z'::timestamptz, 'kofi-jw4b8t', '[]'::jsonb),
  ('20000000-0000-4000-8000-000000000004'::uuid, '10000000-0000-4000-8000-000000000004'::uuid, 'DeShawn Ferris', null, 'he/him', 'Photographer documenting the night shift — bakeries, hospitals, transit yards. Archival pigment prints in small editions.', null, 'Philadelphia', 'Pennsylvania', 'United States', 'country', array['photography', 'video']::kofi.medium[], 'mid-career', true, false, false, true, 11, true, true, false, '[{"label":"Instagram","url":"https://www.instagram.com/deshawn.nightshift","platform":"instagram","handle":"@deshawn.nightshift","verification":"claimed"}]'::jsonb, 'deshawn@example.com', null, null, null, 'public', 'approved', '2026-10-v1', '2026-08-07T12:00:00.000Z'::timestamptz, '#FFD23F', '2026-08-04T12:00:00.000Z'::timestamptz, '2026-08-30T12:00:00.000Z'::timestamptz, 'kofi-df5n7q', '[]'::jsonb),
  ('20000000-0000-4000-8000-000000000005'::uuid, '10000000-0000-4000-8000-000000000005'::uuid, 'Priya Venkataraman', null, 'she/her', 'Printmaker and digital artist. Screen prints that start as code and end as ink.', null, 'Pittsburgh', 'Pennsylvania', 'United States', 'city', array['printmaking', 'digital']::kofi.medium[], 'emerging', false, false, false, false, 2, true, true, true, '[{"label":"Website","url":"https://www.priyavenkataraman.art","platform":"website","handle":"priyavenkataraman.art","verification":"claimed"},{"label":"LinkedIn","url":"https://www.linkedin.com/in/priya-venkataraman","platform":"linkedin","handle":"priya-venkataraman","verification":"unreachable","checkedAt":"2026-08-26T12:00:00.000Z"}]'::jsonb, 'priya@example.com', null, null, 'Submitted for review. Need two more documented works before approval.', 'public', 'pending', '2026-10-v1', '2026-08-26T12:00:00.000Z'::timestamptz, '#5b41e6', '2026-08-25T12:00:00.000Z'::timestamptz, '2026-08-31T12:00:00.000Z'::timestamptz, 'kofi-pv3h8x', '[{"source":{"label":"Website","url":"https://www.priyavenkataraman.art","platform":"website","handle":"priyavenkataraman.art","verification":"claimed"},"fetchedAt":"2026-08-25T12:00:00.000Z","appliedFields":["workingName","bio"],"notes":[]},{"source":{"label":"LinkedIn","url":"https://www.linkedin.com/in/priya-venkataraman","platform":"linkedin","handle":"priya-venkataraman","verification":"claimed"},"fetchedAt":"2026-08-25T12:00:00.000Z","appliedFields":[],"notes":["We could not read a name from the page, so this comes from the handle."]}]'::jsonb);

insert into kofi.demo_artworks (id, artist_id, title, year, medium, materials, height, width, depth, unit, description, status, rights_note, price_amount, price_currency, price_visibility, visibility, tags, reviewed_at, created_at, updated_at, tag_ids, uses, edition, location) values
  ('30000000-0000-4000-8000-000000000011'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'Doubling (Liberty Avenue, 7:40pm)', 2025, 'painting', array['oil on linen']::text[], 152, 122, 4, 'cm', 'A face drawn twice over itself in black brush and red spray, on a ground the colour of wet brick. Eleven passes until the second face reads as the reflection of the first.', 'available', 'Sample listing. The photograph shows a painting by Clarence James (from koficollections.org); it is not by this sample artist.', 9800, 'USD', 'institutions', 'public', array['night', 'city', 'reflection']::text[], '2026-08-12T12:00:00.000Z'::timestamptz, '2026-07-23T12:00:00.000Z'::timestamptz, '2026-08-29T12:00:00.000Z'::timestamptz, array['medium.painting', 'style.expressionism', 'style.figurative', 'subject.urban_life', 'theme.memory', 'material.oil', 'palette.warm']::text[], '{"auction":true,"exhibition":true,"licensing":false,"commission":false}'::jsonb, null, null),
  ('30000000-0000-4000-8000-000000000012'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, 'Small Weather No. 4', 2024, 'painting', array['oil on panel']::text[], 30, 24, null, 'cm', 'A figure submerged in turquoise, painted wet-into-wet in the studio doorway during rain. One of a series.', 'available', 'Sample listing. The photograph shows a work exhibited with Kofi Collections (from koficollections.org); it is not by this sample artist.', 1400, 'USD', 'public', 'public', array['study', 'rain']::text[], '2026-08-12T12:00:00.000Z'::timestamptz, '2026-07-24T12:00:00.000Z'::timestamptz, '2026-08-20T12:00:00.000Z'::timestamptz, array['medium.painting', 'style.figurative', 'subject.people', 'subject.urban_life', 'theme.memory', 'material.oil', 'palette.cool']::text[], '{"auction":true,"exhibition":true,"licensing":false,"commission":false}'::jsonb, null, null),
