-- Programme (0008): exhibitions, open calls, events, stories, applications, collector inquiries.
insert into kofi.demo_exhibitions (id, title, subtitle, starts_on, ends_on, venue, summary, body, image, artwork_ids, external_url, curated_by, sample, published, created_at, updated_at) values
  ('a1000000-0000-4000-8000-000000000001'::uuid, 'Being/Seen', null, '2025-05-08'::date, '2025-10-25'::date, null, 'A group exhibition of 36 Pittsburgh artists of colour working across four modalities.', 'Being/Seen brought together 36 Pittsburgh artists of colour working across four modalities.

The exhibition looked at how Black art and history have been erased or undervalued in exhibitions, and at what it feels like when that history is recognised and celebrated instead.', null, '{}'::uuid[], 'https://www.koficollections.org/upcoming-exhibitions', 'Kofi Collections', false, true, '2026-10-20T13:00:00.000Z'::timestamptz, '2026-10-20T13:00:00.000Z'::timestamptz),
  ('a1000000-0000-4000-8000-000000000002'::uuid, 'The Spirit of the West', null, '2024-09-12'::date, null, null, 'An exhibition honouring Black and Indigenous heritage in the American West.', 'The Spirit of the West honoured Black and Indigenous heritage.

Kofi Collections invited artists to submit works about the histories of these communities and their contributions to the American West, including ranching and Western traditions.', null, '{}'::uuid[], 'https://www.koficollections.org/prior-exhibitions', 'Kofi Collections', false, true, '2026-10-20T13:00:00.000Z'::timestamptz, '2026-10-20T13:00:00.000Z'::timestamptz),
  ('a1000000-0000-4000-8000-000000000003'::uuid, 'I Am', null, '2024-05-03'::date, null, null, 'Overlooked narratives of marginalised groups in the Pittsburgh region, from painting to sculpture.', 'I Am gave space to narratives of marginalised groups in the Pittsburgh region that are often overlooked.

The work on show ranged from paintings to sculpture.', null, '{}'::uuid[], 'https://www.koficollections.org/prior-exhibitions', 'Kofi Collections', false, true, '2026-10-20T13:00:00.000Z'::timestamptz, '2026-10-20T13:00:00.000Z'::timestamptz),
  ('a1000000-0000-4000-8000-000000000004'::uuid, 'Night Weather', 'Four artists on the city after dark', '2026-10-02'::date, '2026-11-22'::date, '{"name":"Kofi Collections","address":"213 Smithfield St.","city":"Pittsburgh, PA"}'::jsonb, 'Paintings, textile, photography and print made at night or about it: wet streets, late shifts, rooms after everyone has gone.', 'Night Weather gathers work by four artists who keep late hours. Mara Oyelaran paints Liberty Avenue in the hour after rain. DeShawn Ferris photographs bakeries and transit yards on the night shift. June Takahashi-Bell weaves with thread salvaged from a closed mill.

The show is hung low and close, so the textile can be touched and the photographs read at arm’s length. Prices are listed on the wall where the artist has chosen to share them.

Every work in the exhibition is documented in the artists’ own records on Kofi Collections. Ask Kofi about any piece and the team will put you in touch.', '{"src":"/art/mara1.jpg","alt":"Face painted in black brush strokes and red spray over a brown ground","credit":"Painting by Clarence James · photograph from koficollections.org"}'::jsonb, array['30000000-0000-4000-8000-000000000011', '30000000-0000-4000-8000-000000000012', '30000000-0000-4000-8000-000000000031', '30000000-0000-4000-8000-000000000041', '30000000-0000-4000-8000-000000000051']::uuid[], null, 'Kofi Collections', true, true, '2026-09-15T14:00:00.000Z'::timestamptz, '2026-10-01T14:00:00.000Z'::timestamptz),
  ('a1000000-0000-4000-8000-000000000005'::uuid, 'Soft Ground', 'Printmaking and textile', '2027-01-15'::date, '2027-03-06'::date, '{"name":"Kofi Collections","address":"213 Smithfield St.","city":"Pittsburgh, PA"}'::jsonb, 'Prints and woven work that share a process: layers laid down slowly, one pass at a time.', 'Soft Ground takes its name from the etching ground that stays tacky, recording anything pressed into it. The exhibition pairs screen prints by Priya Venkataraman with wall textiles by June Takahashi-Bell.

Both artists build an image in passes. The show will add works selected through the Soft Ground open call.', null, array['30000000-0000-4000-8000-000000000052', '30000000-0000-4000-8000-000000000031', '30000000-0000-4000-8000-000000000032']::uuid[], null, 'Kofi Collections', true, true, '2026-10-05T14:00:00.000Z'::timestamptz, '2026-10-05T14:00:00.000Z'::timestamptz);

insert into kofi.demo_open_calls (id, title, partner, summary, body, eligibility, mediums, opens_on, deadline, max_works, fee, award, image, external_url, exhibition_id, sample, published, created_at, updated_at, kind, organizer_institution_id, terms, looking_for) values
  ('a2000000-0000-4000-8000-000000000001'::uuid, 'The Art of Advocacy: Giving Form and Voice to Justice', 'Neighborhood Legal Services', 'An exhibition for Neighborhood Legal Services’ 60th anniversary, ending in an auction on October 6, 2026. Kofi Collections led artist selection.', 'Neighborhood Legal Services marked its 60th anniversary with The Art of Advocacy: Giving Form and Voice to Justice, an exhibition about how artists and lawyers use storytelling, interpretation and advocacy to bring lived experiences to light and to inspire change.

Kofi Collections was the curatorial partner and led the selection of artists. Artists could apply themselves or be nominated; nominated artists completed a full application by the extended deadline of September 11, 2026. The exhibition culminated in an auction on October 6, 2026.', 'Artists could apply themselves or be nominated by someone else. Nominated artists completed a full application.', '{}'::kofi.medium[], '2026-09-11'::date, '2026-09-11'::date, 1, 'See the call', null, null, 'https://www.koficollections.org/artists', null, false, true, '2026-10-20T13:00:00.000Z'::timestamptz, '2026-10-20T13:00:00.000Z'::timestamptz, 'exhibition', null, null, null),
  ('a2000000-0000-4000-8000-000000000002'::uuid, 'Night Weather Studio Award', 'Kofi Collections', 'Show us work made at night or about it. One artist receives a solo wall next spring and a studio grant.', 'The Night Weather Studio Award is open to artists in any medium whose work deals with the city after dark: late shifts, weather, light, the rooms people leave behind.

Attach up to three works from your Kofi portfolio and write a short statement on why they belong together. Works set to Only me cannot be attached; change them to Kofi team only if you want us to see them without publishing.

Kofi reads every application. Shortlisted artists will hear from us within three weeks of the deadline.', 'Artists living or working in Western Pennsylvania', '{}'::kofi.medium[], '2026-10-01'::date, '2026-11-30'::date, 3, 'No entry fee', 'A solo wall in Kofi’s spring 2027 programme and a $1,500 studio grant (sample)', null, null, 'a1000000-0000-4000-8000-000000000004'::uuid, true, true, '2026-09-20T14:00:00.000Z'::timestamptz, '2026-10-01T14:00:00.000Z'::timestamptz, 'award', null, null, '{"tags":{"theme":["theme.memory"],"subject":["subject.urban_life"]},"uses":["exhibition"]}'::jsonb),
  ('a2000000-0000-4000-8000-000000000003'::uuid, 'Soft Ground: Printmakers & Weavers', 'Kofi Collections', 'Printmakers and textile artists: apply to show alongside Soft Ground this winter.', 'Soft Ground will add a small number of works chosen through this call. We are looking for prints and woven or stitched work where the process is visible in the finished piece.

Editions are welcome; tell us the edition size in the work’s record.', 'Printmakers and textile artists in the United States and Canada', array['printmaking', 'textile']::kofi.medium[], '2026-11-15'::date, '2027-01-10'::date, 4, 'No entry fee', null, null, null, 'a1000000-0000-4000-8000-000000000005'::uuid, true, true, '2026-10-05T14:00:00.000Z'::timestamptz, '2026-10-05T14:00:00.000Z'::timestamptz, 'exhibition', null, null, null),
  ('a2000000-0000-4000-8000-000000000004'::uuid, 'Late Summer Open 2026', 'Kofi Collections', 'Kofi’s open call for the autumn hang. Selected works are showing now in Night Weather.', 'The Late Summer Open is Kofi’s call for new work in any medium. Selected works are hung together in the autumn exhibition.

This call has closed. Thank you to everyone who applied.', 'Any artist with an approved Kofi profile', '{}'::kofi.medium[], '2026-08-20'::date, '2026-09-20'::date, 3, 'No entry fee', null, null, null, null, true, true, '2026-08-12T14:00:00.000Z'::timestamptz, '2026-09-21T14:00:00.000Z'::timestamptz, 'exhibition', null, null, null),
  ('a2000000-0000-4000-8000-000000000005'::uuid, 'Night Weather Benefit Auction', 'Carnegie Museum of Art', 'A benefit auction of works from Night Weather, run with Carnegie Museum of Art. Artists receive 70% of the hammer price.', 'Carnegie Museum of Art and Kofi Collections are holding a benefit auction of works selected from artists in the Night Weather programme. Proceeds support the Night Weather programme: Kofi’s share and the museum’s share fund next year’s studio award and the artists’ talks.

Artists set their own reserve, the lowest hammer price they will accept. Artists receive 70% of the hammer price, Kofi 20% and the museum 10%. A 10% buyer’s premium is charged on top of the hammer price. If a work is resold later, the artist is owed a 5% resale royalty under Kofi’s open seller’s contract.

Attach up to two works from your Kofi portfolio. Selected works become lots in the auction.', 'Artists with an approved Kofi profile', '{}'::kofi.medium[], '2026-08-15'::date, '2026-09-30'::date, 2, 'No entry fee', null, null, null, 'a1000000-0000-4000-8000-000000000004'::uuid, true, true, '2026-08-10T14:00:00.000Z'::timestamptz, '2026-08-14T14:00:00.000Z'::timestamptz, 'auction', '40000000-0000-4000-8000-000000000001'::uuid, '{"artistSharePct":70,"kofiSharePct":20,"partnerSharePct":10,"buyerPremiumPct":10,"resaleRoyaltyPct":5,"currency":"USD","paymentNote":"Artists are paid within 30 days of the auction."}'::jsonb, '{"tags":{"theme":["theme.community","theme.memory"]},"uses":["auction"],"region":"Pennsylvania","note":"Work about the city at night and the people who keep it running."}'::jsonb);

