insert into kofi.demo_stories (id, title, dek, kind, body, author, published_on, artist_id, artwork_ids, image, sample, published, created_at, updated_at) values
  ('a5000000-0000-4000-8000-000000000001'::uuid, 'Mara Oyelaran paints the hour after a storm', 'The Pittsburgh painter on thin glazes, wet streets, and why her work is slow.', 'interview', 'Mara Oyelaran works from a converted print shop in Pittsburgh. The old press is still there; she uses its bed as a table for mixing glazes.

Her paintings start in the street. After rain she walks Liberty Avenue with a small sketchbook and notes where the reflections fall. Back in the studio she lays down a first thin layer and waits for it to dry before the next. A large canvas can take eleven passes.

> I paint the hour after a storm, when the city is wet enough to double itself.

Doubling (Liberty Avenue, 7:40pm) is the clearest example. A face is painted twice, the second pass slightly offset, so that one reads as the reflection of the other. Small Weather No. 4 was painted in the studio doorway while it was raining, wet-into-wet, in a single afternoon.

Both works are in Night Weather at Kofi Collections until November 22. Mara gives a talk on glazing at the gallery on October 29.', 'Kofi Collections editorial', '2026-10-14'::date, '20000000-0000-4000-8000-000000000001'::uuid, array['30000000-0000-4000-8000-000000000011', '30000000-0000-4000-8000-000000000012']::uuid[], '{"src":"/art/mara2.jpg","alt":"Figure in deep blue against a turquoise ground","credit":"Photograph from koficollections.org"}'::jsonb, true, true, '2026-10-14T13:00:00.000Z'::timestamptz, '2026-10-14T13:00:00.000Z'::timestamptz),
  ('a5000000-0000-4000-8000-000000000002'::uuid, 'Inside June Takahashi-Bell’s loom room', 'Reclaimed mill thread, hand-dyed wool, and wall works built to be touched.', 'studio visit', 'June Takahashi-Bell’s studio is one room with a floor loom, a dye bench and a wall of thread on cones. Most of the thread came from a mill that closed; June bought what was left on the shelves.

The wool is dyed by hand in small batches, so no two lots match. June treats that as part of the work rather than a problem to solve.

Warp / Weft / Wait is made to be handled. Visitors are encouraged to touch it, and the surface shifts a little each time. Small Loom Studies I–IV are dye tests on silk, sold as a set.

June will run an open studio afternoon at Kofi Collections on November 8, ahead of Soft Ground in January.', 'Kofi Collections editorial', '2026-09-30'::date, '20000000-0000-4000-8000-000000000003'::uuid, array['30000000-0000-4000-8000-000000000031', '30000000-0000-4000-8000-000000000032']::uuid[], '{"src":"/art/june1.jpg","alt":"A dress built from hundreds of hand-stitched feathers over a printed ground","credit":"Photograph from koficollections.org"}'::jsonb, true, true, '2026-09-30T13:00:00.000Z'::timestamptz, '2026-09-30T13:00:00.000Z'::timestamptz),
  ('a5000000-0000-4000-8000-000000000003'::uuid, 'What an artist-owned record changes', 'Every field in a Kofi profile has its own visibility. Here is how that works, and why.', 'essay', 'On Kofi Collections the artist owns the record. Each work, each price and each document has its own setting for who can see it, and the artist can change it at any time.

There are four levels. Public means anyone. Verified institutions means curators whose institution Kofi has checked. Kofi team only means Kofi staff and the artist. Only me means the artist alone.

> A price can be shared with a museum without being published to everyone.

Settings apply to fields, not pages. A painting can be public while its price is shown only to verified institutions. Condition reports and appraisal letters are stored privately and are never shown to the public; when Kofi staff open one, the access is logged and the artist can see it.

Artists can export everything they have entered, as a spreadsheet and as a full data file, whenever they like.', 'Kofi Collections editorial', '2026-09-16'::date, null, '{}'::uuid[], null, true, true, '2026-09-16T13:00:00.000Z'::timestamptz, '2026-09-16T13:00:00.000Z'::timestamptz),
  ('a5000000-0000-4000-8000-000000000004'::uuid, 'The Art of Advocacy: Kofi Collections leads artist selection for Neighborhood Legal Services at 60', 'An exhibition on storytelling and justice, ending in an auction on October 6, 2026.', 'news', 'Neighborhood Legal Services marked its 60th anniversary with The Art of Advocacy: Giving Form and Voice to Justice, an exhibition about how artists and lawyers use storytelling, interpretation and advocacy to bring lived experiences to light and inspire change.

Kofi Collections served as the curatorial partner, leading the selection of artists. Artists could apply themselves or nominate another artist, and nominated artists completed a full application by the extended deadline of September 11, 2026. The exhibition culminated in an auction on October 6, 2026.', 'Kofi Collections', '2026-10-20'::date, null, '{}'::uuid[], null, false, true, '2026-10-20T13:00:00.000Z'::timestamptz, '2026-10-20T13:00:00.000Z'::timestamptz);

insert into kofi.demo_applications (id, call_id, artist_id, artwork_ids, statement, status, decision_note, staff_note, created_at, updated_at, decided_at) values
  ('a3000000-0000-4000-8000-000000000001'::uuid, 'a2000000-0000-4000-8000-000000000004'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, array['30000000-0000-4000-8000-000000000011', '30000000-0000-4000-8000-000000000012']::uuid[], 'Two paintings from the same week of rain: one large, one small. I would like them hung on facing walls so the small one reads as a note on the large one.', 'accepted', 'Selected for Night Weather, opening October 2.', null, '2026-09-02T15:10:00.000Z'::timestamptz, '2026-09-25T16:00:00.000Z'::timestamptz, '2026-09-25T16:00:00.000Z'::timestamptz),
  ('a3000000-0000-4000-8000-000000000002'::uuid, 'a2000000-0000-4000-8000-000000000004'::uuid, '20000000-0000-4000-8000-000000000003'::uuid, array['30000000-0000-4000-8000-000000000031']::uuid[], 'A wall textile woven from thread salvaged from a closed mill. It is meant to be touched, and it changes shape a little each time it is.', 'declined', 'Thank you — we would love to see the new loom work next time.', 'Strong; space-limited.', '2026-09-09T18:40:00.000Z'::timestamptz, '2026-09-25T16:05:00.000Z'::timestamptz, '2026-09-25T16:05:00.000Z'::timestamptz),
  ('a3000000-0000-4000-8000-000000000003'::uuid, 'a2000000-0000-4000-8000-000000000002'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, array['30000000-0000-4000-8000-000000000041', '30000000-0000-4000-8000-000000000042']::uuid[], 'Both pieces were made between 2 and 5am in workplaces that run all night. The print is a single frame; the video is the same kind of room, held for eleven minutes.', 'submitted', null, null, '2026-10-12T02:15:00.000Z'::timestamptz, '2026-10-12T02:15:00.000Z'::timestamptz, null),
  ('a3000000-0000-4000-8000-000000000004'::uuid, 'a2000000-0000-4000-8000-000000000005'::uuid, '20000000-0000-4000-8000-000000000001'::uuid, array['30000000-0000-4000-8000-000000000011', '30000000-0000-4000-8000-000000000012']::uuid[], 'Doubling and Small Weather No. 4 were painted in the same week of rain. I would like both offered, the large one with a reserve I have agreed with Kofi.', 'accepted', 'Selected. Both works will be offered as lots; Kofi will confirm your reserves with you.', 'Reserves agreed by phone: $6,000 and $1,000.', '2026-09-14T15:00:00.000Z'::timestamptz, '2026-10-05T15:00:00.000Z'::timestamptz, '2026-10-05T15:00:00.000Z'::timestamptz),
  ('a3000000-0000-4000-8000-000000000005'::uuid, 'a2000000-0000-4000-8000-000000000005'::uuid, '20000000-0000-4000-8000-000000000004'::uuid, array['30000000-0000-4000-8000-000000000041']::uuid[], 'Print 2/5 of Night Shift: Bakery. The edition is otherwise held back, so this is the only print offered this year.', 'accepted', 'Selected. Your print will be offered as a lot.', null, '2026-09-21T19:30:00.000Z'::timestamptz, '2026-10-05T15:05:00.000Z'::timestamptz, '2026-10-05T15:05:00.000Z'::timestamptz),
  ('a3000000-0000-4000-8000-000000000006'::uuid, 'a2000000-0000-4000-8000-000000000005'::uuid, '20000000-0000-4000-8000-000000000005'::uuid, array['30000000-0000-4000-8000-000000000051']::uuid[], 'A screen print from the Grid Drift series, edition of 20. It started as a few lines of code and ended as ink.', 'declined', 'Thank you. This auction was open to artists with an approved Kofi profile; we would be glad to see your work again once your profile is approved.', 'Profile still in review at the deadline.', '2026-09-28T13:45:00.000Z'::timestamptz, '2026-10-05T15:10:00.000Z'::timestamptz, '2026-10-05T15:10:00.000Z'::timestamptz);

